head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isFirstLoad = false;
// 세션정보를 얻기위한 함수사용
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "", scwin.select_gubun = "";
scwin.trsIdx; // insert, update 구분

scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
            scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
            scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
            scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값
            scwin.select_gubun = (arrPar.length >= 7 ? arrPar[6] : ""); //  구분값

        }

        // alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" +
        //         "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        //    fn_SetIsuCdBtnShow(select_gubun);

        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            await scwin.search();
        } else {
            await scwin.newOnload(); // 신규작성시 호출

        }
        $c.libRoundPanel.PanelToGroupBox(panel_3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08053.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08053.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_DelistDd_onclick
 * @description img_DelistDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_DelistDd_onclick = function() {
    try {
        txa_Remk.Text = "";
        edt_DelistDd.focus();
        popUpCalendar2(edt_DelistDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08053.img_DelistDd_onclick" });
    }
};

/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lce.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08053.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lce.fn_alertMsg('S');
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08053.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no === "") {
            dts_Mst.insertRow();
        }

        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_DelistDd, false);
        }
        scwin.isFirstLoad = true;
        if (scwin.fr_bz_procs_no === "") {
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "DELIST_RSN_CD", "720015");
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "DELIST_RSN_DSC", "상장지수증권 최종거래일 도래");
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "GRND_REGUL_NM", "유가증권시장상장규정 제149조의7");
            // cmb_Rsn_Cd.BindColVal = "690017" ;
            // txb_GrndRegulNm.value = dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL") ;

        }
        // else {
        //    dts_Rsn.AddRow();
        //    dts_Rsn.NameString(dts_Rsn.RowPosition, "CODE")  = dts_Mst.NameString(dts_Mst.RowPosition, "DELIST_RSN_CD") ;
        //    dts_Rsn.NameString(dts_Rsn.RowPosition, "NAME") = dts_Mst.NameString(dts_Mst.RowPosition, "DELIST_RSN_DSC") ;
        // }

        scwin.isFirstLoad = false;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08053.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name edt_DelistDd_OnKillFocus
 * @description edt_DelistDd 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_DelistDd_OnKillFocus = function() {
    // fn_setRemk();

};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount > 0) {
            scwin.Isur_cd = dts_Isu.getCellData(dts_Isu.getRowPosition(), "ISUR_CD");
            if (scwin.fr_bz_procs_no === "") {
                edt_DelistDd.setValue($c.ut.cGetPlusDate2(dts_Isu.getCellData(dts_Isu.getRowPosition(), "LSTTRD_DD"), 1));
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08053.dts_Isu_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        url += "&SCREN_ID=" + "ULDSTF08053.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/Delisting.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_Isu",
            action : "/etn/EtnMktAct.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

