/**
 * @method
 * @name saveTrs
 * @description 매매거래정지종목은 매번 업무처리 번호를 세팅함
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }

    // ELW는 항상  종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    // dts_Mst.NameString(dts_Mst.RowPosition, "ISUR_CD") =  Isur_cd;
    // dts_Mst.NameString(dts_Mst.RowPosition, "DELIST_RSN_CD") =  dts_Rsn.NameString(dts_Rsn.RowPosition, "CODE")  ;
    // dts_Mst.NameString(dts_Mst.RowPosition, "DELIST_RSN_DSC") =  dts_Rsn.NameString(dts_Rsn.RowPosition, "NAME")  ;
    // dts_Mst.NameString(dts_Mst.RowPosition, "DELIST_RSN_CD") =  dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE")  ;

    // alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "2",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_706 + ",DIV_IDX[0]=" + DIV_IDX_ETN_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_ETN_DELLIST_DTL
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/etn/EtnMktAct.do",
        ref : "dts_Mst,dts_Isu",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name dupCheck
 * @description dup Check 처리
 * @param {*} pUpdate pUpdate
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dupCheck = async function(pUpdate) {
    const delistDate = edt_DelistDd.getValue();
    const isuCd = dts_Isu.getCellData(1, "ISU_CD");
    const bzProcsNo = dts_Isu.getCellData(1, "BZ_PROCS_NO");
    let isNotDup = true;
    if (pUpdate) url += "&BZ_PROCS_NO=" + bzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_DupIsu",
        action : "/Delisting.do",
        ref : "",
        target : "dts_DupIsu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const dupIsuCd = dts_DupIsu.getCellData(1, "ISU_CD");
    if (dts_DupIsu.getRowCount() > 0) {
        isNotDup = false;
        await $c.win.alert("동일한 날짜에 상장폐지 지정된 종목이 존재합니다.");
    }
    return isNotDup;
};

/**
 * @method
